script:
if (-not $COMPUTER_NAME) { throw 'COMPUTER_NAME is required' }
Import-Module ActiveDirectory -ErrorAction Ignore
$acct = "$COMPUTER_NAME`$"
$existing = Get-ADComputer -Filter "SamAccountName -eq '$acct'" -ErrorAction Ignore
if ($existing) {
    if ($DESCRIPTION) { Set-ADComputer -Identity $COMPUTER_NAME -Description $DESCRIPTION }
} else {
    $params = @{ Name = $COMPUTER_NAME; Enabled = $true }
    if ($DESCRIPTION) { $params.Description = $DESCRIPTION }
    New-ADComputer @params | Out-Null
}
